import re
parts=[]; start=1
while start <= 7070:
    p = read(f"artifact://109:{start}-{min(start+1999,7070)}")
    for ln in p.split("\n"):
        if ln.startswith("[Showing lines"):
            start = int(re.search(r"Use :(\d+)", ln).group(1)); break
        parts.append(ln)
    else: break
for l in parts:
    if l.startswith("::group::❌") and not re.search(r"(app/test/\S+?\.dart):\s*(.+?)\s*\(failed\)$", l):
        print("UNPARSED >>>", l[:400])
print("---- distinct root-cause signatures across the 44 ----")
import collections
sig=collections.Counter()
fails=[l for l in parts if l.startswith("::group::❌")]
for i,l in enumerate(fails):
    tail="\n".join(parts[i+1:i+4])
    for key in ["PathNotFoundException","RenderFlex overflowed","No ProviderScope found",
                "Binding has not yet been initialized","locale","timeAgo","Expected: contains",
                "Expected: exactly one matching candidate","StateError","TypeError","Bad state"]:
        if key in tail or key in l:
            sig[key]+=1; break
    else:
        sig["<other>"]+=1
for k,v in sig.most_common(): print(f"  {v:3}  {k}")

